  function setupCanvasTools(){if($('#brushSize'))return;const fillButton=$('.tool[data-tool="fill"]');fillButton.insertAdjacentHTML('afterend','<button class="tool" data-tool="eyedropper" title="Cuentagotas (O)"><span>◉</span>Cuentagotas</button>');$('.tool[data-tool="eyedropper"]').onclick=()=>selectTool('eyedropper');$('.zoom-controls').insertAdjacentHTML('afterbegin','<span id="cursorCoords" class="cursor-coords">X — · Y —</span><label class="compact-control">Pincel <select id="brushSize"><option>1</option><option>2</option><option>3</option><option>4</option></select></label><label class="compact-control"><input id="shapeFill" type="checkbox"> Fill</label><select id="zoomPreset" title="Zoom"><option value="100">100%</option><option value="200">200%</option><option value="400">400%</option><option value="800">800%</option></select><button id="zoomFit" title="Ajustar canvas">Fit</button>');$('#brushSize').onchange=e=>brushSize=Math.max(1,Math.min(4,+e.target.value));$('#shapeFill').onchange=e=>shapeFill=e.target.checked;$('#zoomPreset').onchange=e=>{zoom=+e.target.value;pan={x:0,y:0};fitCanvas()};$('#zoomFit').onclick=()=>{zoom=100;pan={x:0,y:0};$('#zoomPreset').value='100';fitCanvas()};$('#zoomIn').onclick=()=>{const levels=[100,200,400,800];zoom=levels.find(v=>v>zoom)||800;$('#zoomPreset').value=String(zoom);fitCanvas()};$('#zoomOut').onclick=()=>{const levels=[800,400,200,100];zoom=levels.find(v=>v<zoom)||100;$('#zoomPreset').value=String(zoom);fitCanvas()};canvas.addEventListener('wheel',e=>{if(!e.ctrlKey)return;e.preventDefault();const levels=[100,200,400,800],i=Math.max(0,levels.indexOf(zoom)),next=levels[Math.max(0,Math.min(levels.length-1,i+(e.deltaY<0?1:-1)))];zoom=next;$('#zoomPreset').value=String(zoom);fitCanvas()},{passive:false});canvas.addEventListener('pointerleave',()=>$('#cursorCoords').textContent='X — · Y —')}
  async function setupDeviceRegistry(){const select=$('#deviceSelect');let devices=[SIMULATOR_DEVICE];try{const response=await fetch('/api/devices',{cache:'no-store'});if(response.ok)devices=await response.json()}catch{}devicesById=new Map(devices.map(device=>[device.id,device]));if(!devicesById.has(SIMULATOR_DEVICE.id))devicesById.set(SIMULATOR_DEVICE.id,SIMULATOR_DEVICE);select.innerHTML='';for(const device of devicesById.values()){const option=document.createElement('option');option.value=device.id;option.textContent=`${device.name}${device.address?' · '+device.address:''}`;select.append(option)}const saved=localStorage.getItem('atlas-selected-device');selectedDevice=devicesById.get(saved)||devicesById.get(selectedDevice.id)||SIMULATOR_DEVICE;select.value=selectedDevice.id;select.onchange=()=>{const definition=devicesById.get(select.value);if(!definition)return;selectedDevice={...definition};localStorage.setItem('atlas-selected-device',definition.id);deviceGeneration++;deviceOnline=false;pollDevice();pollOutput()};Object.defineProperty(window,'selectedDevice',{configurable:true,get:()=>selectedDevice});window.atlasDeviceRegistry=[...devicesById.values()]}
  function setupProjectsUx(){if($('#saveState'))return;$('#dirtyIndicator').insertAdjacentHTML('afterend',' <b id="saveState" data-state="guardado">Guardado</b>');window.addEventListener('beforeunload',event=>{if(project?.dirty&&!autosaveConfirmed){event.preventDefault();event.returnValue=''}})}
  async function pollStatus(){if(statusBusy)return;statusBusy=true;try{const response=await fetch(deviceUrl('status'),{cache:'no-store'});if(!response.ok)throw new Error('Sin respuesta');const status=await response.json(),caps=status.device;lastRuntime=status.runtime;deviceOnline=true;selectedDevice.online=true;selectedDevice.capabilities=caps;$('#deviceState').className='device-state online';$('#deviceState').innerHTML='<i></i> Conectado';$('#deviceName').textContent=selectedDevice.name;$('#deviceDetails').textContent=`${caps.width} × ${caps.height} · ${caps.drivers[0]}`;$('#deviceCheck').textContent='✓';$('#runtimeState').textContent=status.runtime.isPlaying?'PLAYING':'STOPPED';$('#outputDevice').textContent=selectedDevice.name;$('#outputScene').textContent=status.runtime.activeSceneName||'Sin escena';$('#outputStatus').textContent=status.runtime.isPlaying?'Reproduciendo':'Detenido';$('#outputBrightness').textContent=Math.round(status.runtime.brightness/2.55)+'%'}catch{deviceOnline=false;selectedDevice.online=false;selectedDevice.capabilities=null;$('#deviceState').className='device-state offline';$('#deviceState').innerHTML='<i></i> Offline';$('#runtimeState').textContent='OFFLINE';$('#deviceCheck').textContent='!';$('#outputStatus').textContent='Sin conexión'}finally{statusBusy=false}}
  function compareOutput(runtime,snapshot){const indicator=$('#outputMatch');if(!indicator)return;const sameScene=runtime.activeSceneId&&project.lastSent?.sceneId?.toLowerCase()===runtime.activeSceneId.toLowerCase()&&project.lastSent.version===project.version,sameSize=snapshot.width===project.width&&snapshot.height===project.height,local=sameSize?raster(runtime.positionSeconds||0):[],level=(runtime.brightness??255)/255;let same=sameScene&&sameSize;if(same)for(let i=0;i<local.length;i++){const expected=local[i],actual=snapshot.pixels[i]?.color||{},r=Math.round((expected>>16&255)*level),g=Math.round((expected>>8&255)*level),b=Math.round((expected&255)*level);if(r!==(actual.r||0)||g!==(actual.g||0)||b!==(actual.b||0)){same=false;break}}indicator.textContent=same?'✓ COINCIDE':'⚠ DIFERENTE';indicator.className='chip '+(same?'match':'different');if(followOutput&&sameSize)drawPixels(local,ctx,canvas,project.brightness)}
  function renderOutputMetadata(data){const caps=data.device||selectedDevice.capabilities,snapshot=data.snapshot,runtime=data.runtime;if(!caps||!snapshot||!runtime)return;$('#outputDevice').textContent=selectedDevice.name;$('#outputDeviceId').textContent=caps.device||'—';$('#outputResolution').textContent=`${snapshot.width} × ${snapshot.height}`;$('#outputColorModel').textContent=snapshot.colorModel===0?'RGB':snapshot.colorModel===1?'RGBW':'—';$('#outputDriver').textContent=caps.drivers?.[0]||'—';$('#outputStatus').textContent=runtime.isPlaying?'Reproduciendo':'Detenido';$('#outputScene').textContent=runtime.activeSceneName||'—';$('#outputSceneId').textContent=runtime.activeSceneId||'—';$('#outputBrightness').textContent=Number.isFinite(runtime.brightness)?Math.round(runtime.brightness/2.55)+'%':'—';$('#outputPosition').textContent=Number.isFinite(runtime.positionSeconds)?formatTime(runtime.positionSeconds):'—';$('#outputFps').textContent=Number.isFinite(data.targetFramesPerSecond)?String(data.targetFramesPerSecond):'—';$('#outputUpdated').textContent=data.updatedAtUtc?new Date(data.updatedAtUtc).toLocaleTimeString():'—'}
  async function pollOutput(){if(document.hidden||outputBusy)return;outputBusy=true;const generation=deviceGeneration,id=selectedDevice.id;try{const response=await fetch(deviceUrl('output'),{cache:'no-store'});if(!response.ok)throw new Error('Sin respuesta');const data=await response.json();if(generation!==deviceGeneration||id!==selectedDevice.id)return;lastRuntime=data.runtime;selectedDevice.capabilities=data.device||selectedDevice.capabilities;if(data.snapshot){drawSnapshot(data.snapshot);compareOutput(data.runtime,data.snapshot)}renderOutputMetadata(data);updateContextDevice()}catch{}finally{outputBusy=false}}
  function outputLoop(){pollOutput().finally(()=>setTimeout(outputLoop,document.hidden?1000:100))}
  function statusLoop(){pollStatus().finally(()=>setTimeout(statusLoop,document.hidden?2000:1000))}
  function setupOutputUx(){const panel=$('#simulatorPanel'),list=panel.querySelector('dl');list.innerHTML='<dt>Dispositivo</dt><dd id="outputDevice">—</dd><dt>DeviceId</dt><dd id="outputDeviceId">—</dd><dt>Resolución</dt><dd id="outputResolution">—</dd><dt>Color model</dt><dd id="outputColorModel">—</dd><dt>Driver</dt><dd id="outputDriver">—</dd><dt>Estado</dt><dd id="outputStatus">—</dd><dt>Escena</dt><dd id="outputScene">—</dd><dt>SceneId</dt><dd id="outputSceneId">—</dd><dt>Brillo</dt><dd id="outputBrightness">—</dd><dt>Posición</dt><dd id="outputPosition">—</dd><dt>FPS objetivo</dt><dd id="outputFps">—</dd><dt>Última actualización</dt><dd id="outputUpdated">—</dd>';$('#stopDeviceButton').insertAdjacentHTML('beforebegin','<div class="dialog-actions output-actions"><button class="button" id="followOutputButton">Seguir salida</button><button class="button" id="outputGridButton">Cuadrícula</button><button class="button" id="expandOutputButton">Ampliar salida</button><span id="outputMatch" class="chip">⚠ DIFERENTE</span></div>');$('#followOutputButton').onclick=()=>{followOutput=!followOutput;$('#followOutputButton').classList.toggle('primary',followOutput);if(!followOutput)render()};$('#outputGridButton').onclick=()=>{outputGrid=!outputGrid;$('#outputGridButton').classList.toggle('primary',outputGrid);pollOutput()};$('#expandOutputButton').onclick=()=>{const expanded=panel.classList.toggle('expanded');$('#expandOutputButton').textContent=expanded?'Reducir salida':'Ampliar salida'};document.addEventListener('visibilitychange',()=>{if(!document.hidden)pollOutput()})}
  pollDevice=pollStatus;const initializeEditor=init;init=async()=>{setupOutputUx();setupCanvasTools();void setupDeviceRegistry();setupProjectsUx();setupContextInspector();setupResolutionChange();await initializeEditor();normalizeProject(project);project.lastSaveKind||='saved';await putProject(clone(project));setSaveState('Guardado');statusLoop();outputLoop()};
  window.addEventListener('keydown',e=>{const typing=['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.target.isContentEditable;if(typing)return;if(e.key==='Delete'&&selectedId){e.preventDefault();$('#deleteObjectButton').click()}if(e.key==='Escape'&&pointer)finishPointer({pointerId:pointer.id},true)});
  window.addEventListener('keydown',e=>{const typing=['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.target.isContentEditable;if(typing)return;const ctrl=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();if(e.code==='Space'){spaceDown=true;canvas.classList.add('pan-ready');e.preventDefault()}if(ctrl&&key==='d'){e.preventDefault();duplicateSelected()}else if(ctrl&&key==='c'&&selectedId){e.preventDefault();objectClipboard=clone(allObjects().find(o=>o.id===selectedId))}else if(ctrl&&key==='v'&&objectClipboard){e.preventDefault();const layer=activeLayer();if(!layer.locked){mutate(()=>{const copy=clone(objectClipboard);copy.id=uid();copy.x=(copy.x||0)+1;copy.y=(copy.y||0)+1;if(['line','rectangle','circle'].includes(copy.type)){copy.x2++;copy.y2++}layer.objects.push(copy);selectedId=copy.id})}}else if(['arrowleft','arrowright','arrowup','arrowdown'].includes(key)&&selectedId){e.preventDefault();const amount=e.shiftKey?5:1;moveSelected(key==='arrowleft'?-amount:key==='arrowright'?amount:0,key==='arrowup'?-amount:key==='arrowdown'?amount:0)}else if(key==='o')selectTool('eyedropper')});
